# Catechism bank — the verb Q&A (research/sources/mensubat.txt, fifth section, items 1-12).
ITEMS = [
 {"n": 1, "q": {"tr": "Fiilin tarifi nedir? Fiilin hâssaları nelerdir?", "en": "How is the verb defined, and what are its marks?"},
  "a": {"tr": "Kendi başına bir mânâya, üç zamandan birine bağlı olarak delâlet edendir. Hâssaları: قَدْ, sîn, سَوْفَ; cer harfi ve lâm-ı ta'rif almaması; sâkin tâ-i te'nîsin ve merfû zamir olan harekeli tâ'nın bitişmesi.",
        "en": "What signifies a meaning in itself tied to one of the three times. Its marks: قَدْ, the sīn, سَوْفَ; refusing the jarr letter and the article; taking the still tāʾ of the feminine and the vowelled tāʾ as its rafʿ pronoun."},
  "ar": ["مَا دَلَّ عَلَى مَعْنًى فِي نَفْسِهِ مُقْتَرِنٍ بِأَحَدِ الْأَزْمِنَةِ الثَّلَاثَةِ"], "notes": ["al-fil-wal-madi-wal-mudari-fil-kafiya", "al-kalima-wal-kalam"], "story": "al-kafiya", "chapter": 20},
 {"n": 2, "q": {"tr": "Fiil-i mâzî ve fiil-i muzârinin tarifi nedir? Fiillerden hangisi mu'rabdır?", "en": "How are the past and present verbs defined, and which verb is declinable?"},
  "a": {"tr": "Mâzî: senin zamanından önceki bir zamana delâlet edendir. Muzâri: نَأَيْتَ harflerinden biriyle isme benzeyendir. Yalnız muzâri mu'rabdır, çünkü lafzan, mânen ve isti'mâlen ism-i fâile benzer; ancak te'kîd nûnu ve cem'-i müennes nûnu bitişen muzâri mebnîdir (يَضْرِبَنَّ، يَضْرِبْنَ).",
        "en": "The past: what signifies a time before your own. The present: what resembles the noun by one of the letters of نَأَيْتَ. Only the present is declinable, resembling the active participle in wording, meaning and use; but a present with the nūn of emphasis or the nūn of the feminine plural is built (يَضْرِبَنَّ، يَضْرِبْنَ)."},
  "ar": ["مَا دَلَّ عَلَى زَمَانٍ قَبْلَ زَمَانِكَ", "مَا أَشْبَهَ الِاسْمَ بِأَحَدِ حُرُوفِ نَأَيْتَ", "يَضْرِبَنَّ", "يَضْرِبْنَ"], "notes": ["al-fil-wal-madi-wal-mudari-fil-kafiya", "al-mabni-ghayr-al-lazim-tawabi-al-munada-wa-huruf-al-nida-wa-ism-la-wal-mudari-bil-nun"], "story": "al-kafiya", "chapter": 20},
 {"n": 3, "q": {"tr": "Fiil-i muzâri ne ile nasb olur? Şartları nelerdir?", "en": "By what is the present verb put in naṣb, and on what conditions?"},
  "a": {"tr": "أَنْ، لَنْ، إِذَنْ'den biriyle ve حَتَّى, lâm-ı كَيْ, lâm-ı cuhûd, fâ, vâv, أَوْ'den sonra gelen mukadder أَنْ ile. إِذَنْ'in amel şartı ikidir: fiili istikbal olacak; mâba'di mâkabline dayanmayacak. حَتَّى'dan sonra أَنْ'in takdiri için muzâri mâkabline nisbetle istikbal, حَتَّى ise كَيْ ya da إِلَى mânâsında olacak. Fâ'dan sonra: sebebiyye olmak ve mâkablinde emir, nehiy, istifham, nefiy, temennî, arz'dan biri bulunmak. Vâv'dan sonra: cem'iyyet için olmak ve mâkablinde aynı altıdan biri bulunmak. أَوْ'den sonra: إِلَى أَنْ ya da إِلَّا أَنْ mânâsında olmak. Ma'tûfun aleyh isim olduğunda bütün atıf harflerinden sonra muzâri mukadder أَنْ ile nasb olur.",
        "en": "By أَنْ، لَنْ، إِذَنْ, and by an implied أَنْ after حَتَّى, the lām of كَيْ, the lām of denial, the fāʾ, the wāw and أَوْ. إِذَنْ governs on two conditions: its verb is future, and what follows does not lean on what precedes. After حَتَّى: the verb is future relative to what precedes, and حَتَّى means كَيْ or إِلَى. After the fāʾ: it is causal and follows a command, prohibition, question, negation, wish or offer. After the wāw: it means accompaniment and follows one of the same six. After أَوْ: it means إِلَى أَنْ or إِلَّا أَنْ. When the thing coordinated to is a noun, the present takes naṣb by an implied أَنْ after any coordinating letter."},
  "ar": [], "notes": ["nawasib-al-mudari-fil-kafiya", "nawasib-wa-jawazim-al-mudari", "an-masdariyya"], "story": "al-kafiya", "chapter": 21},
 {"n": 4, "q": {"tr": "Fiil-i muzâri nelerle cezm olur?", "en": "By what is the present verb put in jazm?"},
  "a": {"tr": "لَمْ، لَمَّا, emir lâmı, nehiy لَا'sı, إِنْ، مَهْمَا، إِذْمَا، حَيْثُمَا، أَيْنَ، مَتَى، مَا، مَنْ، أَيٌّ، أَنَّى ile; ve mâkabli sebep olmak üzere emir, nehiy, istifham, temennî ve arz'dan sonra gelen muzâri mukadder إِنْ ile cezm olur.",
        "en": "By لَمْ، لَمَّا, the lām of command, the لَا of prohibition, إِنْ، مَهْمَا، إِذْمَا، حَيْثُمَا، أَيْنَ، مَتَى، مَا، مَنْ، أَيٌّ، أَنَّى; and by an implied إِنْ when the present follows a command, prohibition, question, wish or offer as its consequence."},
  "ar": [], "notes": ["jawazim-al-mudari-wal-amr-fil-kafiya", "nawasib-wa-jawazim-al-mudari", "lam-jazim"], "story": "al-kafiya", "chapter": 22},
 {"n": 5, "q": {"tr": "Şart ve cezâ cümlelerinin hükümleri nelerdir?", "en": "What are the rulings of the condition and its answer?"},
  "a": {"tr": "İkisi de muzâri ise ya da birincisi muzâri ise muzârinin cezmi vâciptir; yalnız cezâ muzâri ise cezâda cezm ve ref' câizdir. Cezâ قَدْ'sız lafzan ya da mânen mâzî ise fâ giremez; müsbet muzâri ya da لَا ile menfî ise fâ getirmek de getirmemek de câizdir; قَدْ'lı mâzî ya da لَمْ ve لَنْ ile menfî muzâri ise fâ vâciptir.",
        "en": "If both are present verbs, or the first is, the jazm is obligatory; if only the answer is a present, it may be in jazm or rafʿ. When the answer is a past verb without قَدْ, in wording or in sense, no fāʾ may enter; when it is an affirmed present or one negated by لَا, the fāʾ is optional; when it is a past with قَدْ or a present negated by لَمْ or لَنْ, the fāʾ is obligatory."},
  "ar": [], "notes": ["al-majzum-wal-shart-wal-jaza", "al-fa-fi-jawab-al-shart", "huruf-al-shart-fil-kafiya"], "story": "al-kafiya", "chapter": 41},
 {"n": 6, "q": {"tr": "Emrin tarifi nedir?", "en": "How is the imperative defined?"},
  "a": {"tr": "Muzâraat harfinin hazfiyle muhâtab fâilden fiilin kendisiyle istendiği sîgadır: اُقْتُلْ، اِضْرِبْ.", "en": "A form by which the act is sought from the addressed doer, with the present's prefix dropped: اُقْتُلْ، اِضْرِبْ."},
  "ar": ["صِيغَةٌ يُطْلَبُ بِهَا الْفِعْلُ مِنَ الْفَاعِلِ الْمُخَاطَبِ بِحَذْفِ حَرْفِ الْمُضَارَعَةِ", "اُقْتُلْ", "اِضْرِبْ"], "notes": ["imperative-amr", "al-amr-wa-wujuhuh", "jawazim-al-mudari-wal-amr-fil-kafiya"], "story": "al-kafiya", "chapter": 22},
 {"n": 7, "q": {"tr": "Meçhul fiilin tarifi nedir?", "en": "How is the passive verb defined?"},
  "a": {"tr": "Fâili hazfedilip mef'ûlü fâilin yerine konulandır.", "en": "That whose doer is dropped and whose object is set in its place."},
  "ar": ["هُوَ مَا حُذِفَ فَاعِلُهُ وَأُقِيمَ هُوَ مَقَامَهُ"], "notes": ["al-majhul-fil-kafiya", "naib-al-fail"], "story": "al-kafiya", "chapter": 23},
 {"n": 8, "q": {"tr": "Müteaddî fiilin tarifi nedir? Kaç kısımdır? Lâzım fiilin tarifi nedir?", "en": "How is the transitive verb defined, how many kinds has it, and how is the intransitive defined?"},
  "a": {"tr": "Müteaddî: anlaşılması bir müteallaka bağlı olandır. Üç kısım: bir mef'ûle (ضَرَبَ); iki mef'ûle — ikinci mef'ûlü birincisine zıt olan (أَعْطَيْتُ bâbı), ef'âl-i kulûb (عَلِمْتُ), kulûbe mülhak olanlar (صَيَّرَ، جَعَلَ); üç mef'ûle (أَعْلَمَ، أَرَى، أَنْبَأَ، نَبَّأَ، أَخْبَرَ، خَبَّرَ، حَدَّثَ). Lâzım: anlaşılması bir müteallaka bağlı olmayandır (قَعَدَ).",
        "en": "Transitive: what cannot be understood without something it reaches. Three kinds: to one object (ضَرَبَ); to two — the second unlike the first (the أَعْطَيْتُ class), the verbs of the heart (عَلِمْتُ), and those joined to them (صَيَّرَ، جَعَلَ); to three (أَعْلَمَ، أَرَى، أَنْبَأَ، نَبَّأَ، أَخْبَرَ، خَبَّرَ، حَدَّثَ). Intransitive: what is understood without one (قَعَدَ)."},
  "ar": ["مَا يَتَوَقَّفُ فَهْمُهُ عَلَى مُتَعَلَّقٍ", "مَا لَا يَتَوَقَّفُ فَهْمُهُ عَلَى مُتَعَلَّقٍ"], "notes": ["al-lazim-wal-mutaaddi", "al-mutaaddi-wa-afal-al-qulub-fil-kafiya", "mafulayn"], "story": "al-kafiya", "chapter": 24},
 {"n": 9, "q": {"tr": "Ef'âl-i kulûbun tarifi nedir? Nelerdir? Husûsiyetleri nelerdir?", "en": "How are the verbs of the heart defined, which are they, and what is peculiar to them?"},
  "a": {"tr": "Kalbî bir fiile delâlet eden, mübteda ve haber üzerine girip ikisini mef'ûliyyet üzere nasbeden fiillerdir: عَلِمْتُ، رَأَيْتُ، وَجَدْتُ (ilim), زَعَمْتُ (zan ve ilim), ظَنَنْتُ، خِلْتُ، حَسِبْتُ (zan), اِحْسَبْ mânâsında هَبْ. Husûsiyetleri: ma'mûllerinin arasına girince ya da onlardan sonra gelince amel ettirmek de ilgâ etmek de câizdir (زَيْدًا عَلِمْتُ مُنْطَلِقًا / زَيْدٌ عَلِمْتُ مُنْطَلِقٌ; زَيْدًا مُنْطَلِقًا عَلِمْتُ / زَيْدٌ مُنْطَلِقٌ عَلِمْتُ); fâil ve mef'ûlü aynı mânâda iki muttasıl zamir olabilir (عَلِمْتُنِي قَائِمًا); mef'ûllerine أَنَّ girebilir (عَلِمْتُ أَنَّ زَيْدًا قَائِمٌ); sonrasına istifham, nefiy harfi ya da ibtidâ lâmı gelince ta'lîk vâki olur (عَلِمْتُ أَزَيْدٌ عِنْدَكَ أَمْ عَمْرٌو).",
        "en": "Verbs that signify an act of the heart, enter on mubtadaʾ and khabar and put both in naṣb as objects: عَلِمْتُ، رَأَيْتُ، وَجَدْتُ (knowing), زَعَمْتُ (knowing or supposing), ظَنَنْتُ، خِلْتُ، حَسِبْتُ (supposing), and هَبْ for اِحْسَبْ. Their peculiarities: standing between their governed words, or after them, they may govern or be suspended (زَيْدًا عَلِمْتُ مُنْطَلِقًا / زَيْدٌ عَلِمْتُ مُنْطَلِقٌ; زَيْدًا مُنْطَلِقًا عَلِمْتُ / زَيْدٌ مُنْطَلِقٌ عَلِمْتُ); their doer and object may be two attached pronouns of one referent (عَلِمْتُنِي قَائِمًا); أَنَّ may enter on their objects (عَلِمْتُ أَنَّ زَيْدًا قَائِمٌ); and a question, a negation or the lām of ibtidāʾ after them suspends their work (عَلِمْتُ أَزَيْدٌ عِنْدَكَ أَمْ عَمْرٌو)."},
  "ar": ["وَهِيَ أَفْعَالٌ دَالَّةٌ عَلَى فِعْلٍ قَلْبِيٍّ دَاخِلَةٌ عَلَى الْمُبْتَدَإِ وَالْخَبَرِ نَاصِبَةٌ إِيَّاهُمَا عَلَى الْمَفْعُولِيَّةِ", "زَيْدًا عَلِمْتُ مُنْطَلِقًا", "عَلِمْتُنِي قَائِمًا", "عَلِمْتُ أَزَيْدٌ عِنْدَكَ أَمْ عَمْرٌو"], "notes": ["zanna-wa-akhawatuha", "al-mutaaddi-wa-afal-al-qulub-fil-kafiya", "al-mutaaddi-wa-afal-al-qulub"], "story": "al-kafiya", "chapter": 24},
 {"n": 10, "q": {"tr": "Ef'âl-i nâkısanın tarifi nedir? Nelerdir?", "en": "How are the defective verbs defined, and which are they?"},
  "a": {"tr": "Fâili bir sıfat üzere karar kıldırmak için konulan fiillerdir: كَانَ، صَارَ، آلَ، رَجَعَ، حَالَ، اسْتَحَالَ، تَحَوَّلَ، ارْتَدَّ، جَاءَ، قَعَدَ، أَصْبَحَ، أَمْسَى، أَضْحَى، ظَلَّ، بَاتَ، آضَ، عَادَ، غَدَا، رَاحَ، مَا زَالَ، مَا فَتِئَ، مَا أَفْتَأَ، مَا بَرِحَ، مَا وَنِيَ، مَا رَامَ، مَا دَامَ، لَيْسَ. Haberlerini kendilerinin önüne almak câizdir; مَا ile başlayanlarda câiz değildir; لَيْسَ'de ihtilaflıdır.",
        "en": "Verbs coined to settle the doer on a quality: كَانَ، صَارَ، آلَ، رَجَعَ، حَالَ، اسْتَحَالَ، تَحَوَّلَ، ارْتَدَّ، جَاءَ، قَعَدَ، أَصْبَحَ، أَمْسَى، أَضْحَى، ظَلَّ، بَاتَ، آضَ، عَادَ، غَدَا، رَاحَ، مَا زَالَ، مَا فَتِئَ، مَا أَفْتَأَ، مَا بَرِحَ، مَا وَنِيَ، مَا رَامَ، مَا دَامَ، لَيْسَ. Their khabar may precede them, except for those opening with مَا; لَيْسَ is disputed."},
  "ar": ["مَا وُضِعَ لِتَقْرِيرِ الْفَاعِلِ عَلَى صِفَةٍ"], "notes": ["kana-wa-akhawatuha", "al-afal-al-naqisa-fil-kafiya"], "story": "al-kafiya", "chapter": 25},
 {"n": 11, "q": {"tr": "Ef'âl-i mukârebenin tarifi nedir? Nelerdir?", "en": "How are the verbs of approach defined, and which are they?"},
  "a": {"tr": "Haberi fâile umarak, hâsıl olarak ya da ona başlayarak yaklaştırmak için konulan fiillerdir. Umma: عَسَى — ya isim sonra muzâri (عَسَى زَيْدٌ أَنْ يَخْرُجَ) ya muzâri sonra isim (عَسَى أَنْ يَخْرُجَ زَيْدٌ). Hâsıl olma: كَادَ. Başlama: طَفِقَ، كَرَبَ، جَعَلَ، أَخَذَ، أَوْشَكَ.",
        "en": "Verbs coined to bring the khabar near the doer in hope, in occurrence, or in setting about it. Hope: عَسَى — noun then present (عَسَى زَيْدٌ أَنْ يَخْرُجَ) or present then noun (عَسَى أَنْ يَخْرُجَ زَيْدٌ). Occurrence: كَادَ. Setting about: طَفِقَ، كَرَبَ، جَعَلَ، أَخَذَ، أَوْشَكَ."},
  "ar": ["مَا وُضِعَ لِدُنُوِّ الْخَبَرِ رَجَاءً أَوْ حُصُولًا أَوْ أَخْذًا فِيهِ", "عَسَى زَيْدٌ أَنْ يَخْرُجَ"], "notes": ["afal-al-muqaraba-fil-kafiya", "afal-al-muqaraba"], "story": "al-kafiya", "chapter": 26},

 {"n": 12, "q": {"tr": "Fiil-i taaccübün tarifi nedir? Sîgaları nelerdir?", "en": "How is the verb of wonder defined, and what are its forms?"},
  "a": {"tr": "Taaccüb inşâ etmek için konulan fiildir. İki sîgası vardır: مَا أَفْعَلَهُ ve أَفْعِلْ بِهِ. Mezîd bablarda أَشَدَّ lafzıyla gelir.", "en": "A verb coined to voice wonder. Two forms: مَا أَفْعَلَهُ and أَفْعِلْ بِهِ. From the augmented classes it comes with أَشَدَّ."},
  "ar": ["مَا وُضِعَ لِإِنْشَاءِ التَّعَجُّبِ", "مَا أَفْعَلَهُ", "أَفْعِلْ بِهِ"], "notes": ["fil-al-taajjub-fil-kafiya"], "story": "al-kafiya", "chapter": 27},
 {"n": 13, "q": {"tr": "Ef'âl-i medh ve ef'âl-i zemmin tarifi nedir? Nelerdir? Amel şartları nelerdir?", "en": "How are the verbs of praise and blame defined, which are they, and on what conditions do they govern?"},
  "a": {"tr": "Ef'âl-i medh: medh inşâ etmek için konulan fiildir — نِعْمَ. Ef'âl-i zem: zem inşâ etmek için konulan fiildir — بِئْسَ. Amel şartları üçtür: fâilleri lâm ile ma'rife, ya da lâm ile ma'rifeye muzâf, ya da nekre ile temyiz edilmiş müzmer olacak (نِعْمَ رَجُلًا زَيْدٌ).",
        "en": "The verb of praise: what is coined to voice praise — نِعْمَ. The verb of blame: what is coined to voice blame — بِئْسَ. Three conditions for governing: the doer bears the article, or is annexed to a noun bearing it, or is a hidden pronoun made distinct by an indefinite tamyīz (نِعْمَ رَجُلًا زَيْدٌ)."},
  "ar": ["مَا وُضِعَ لِإِنْشَاءِ مَدْحٍ", "مَا وُضِعَ لِإِنْشَاءِ ذَمٍّ", "نِعْمَ رَجُلًا زَيْدٌ"], "notes": ["afal-al-madh-wal-dhamm-fil-kafiya", "takid-al-madh-wal-dhamm"], "story": "al-kafiya", "chapter": 27},
 {"n": 14, "q": {"tr": "نِعْمَ الرَّجُلُ زَيْدٌ misalinde kaç terkib vardır?", "en": "How many constructions has نِعْمَ الرَّجُلُ زَيْدٌ?"},
  "a": {"tr": "İki vecih: نِعْمَ fiil, الرَّجُلُ fâil olup cümle-i fiiliyye mukaddem haber, mahsûs olan زَيْدٌ muahhar mübtedadır; ya da نِعْمَ الرَّجُلُ müstakil bir cümle-i fiiliyye, زَيْدٌ ise mahzûf mübteda هُوَ'nin haberi olup müstakil bir cümledir.",
        "en": "Two readings: نِعْمَ is the verb and الرَّجُلُ its doer, the verbal sentence a fronted khabar and the specified زَيْدٌ a postponed mubtadaʾ; or نِعْمَ الرَّجُلُ is an independent verbal sentence and زَيْدٌ the khabar of a dropped هُوَ, a second independent sentence."},
  "ar": ["نِعْمَ الرَّجُلُ زَيْدٌ"], "notes": ["afal-al-madh-wal-dhamm-fil-kafiya"], "story": "al-kafiya", "chapter": 27},
]
